import{_ as t,o,c as d,ag as n}from"./chunks/framework.BZohXCq9.js";const h=JSON.parse('{"title":"Admin Dashboard -> Document Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/document-management.md","filePath":"modules/admin-dashboard/document-management.md"}'),s={name:"modules/admin-dashboard/document-management.md"};function a(r,e,i,c,l,u){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="admin-dashboard-document-management-deep" tabindex="-1">Admin Dashboard -&gt; Document Management (deep) <a class="header-anchor" href="#admin-dashboard-document-management-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Document Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>document-management</code><br><strong>Routes:</strong> <code>/admin-dashboard/documentsManagement</code>, <code>/admin-dashboard/document-details/:instructorId/:documentType</code></p><p>This module shows uploaded instructor documents, groups Swiss driving-license files, lets the admin change document status, and opens a dedicated detail view for each document type.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all instructor documents in one admin table.</li><li>Filter by instructor, search text, and document status.</li><li>Open a detail page for a specific instructor/document type.</li><li>Accept, reject, or reset document status.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/components/AdminComponents/InstructorDocumentsTable.tsx</code></td><td>Main documents list screen used by the route</td><td>Calls <code>GET_ALL_INSTRUCTORS</code>, flattens <code>instructor.documents</code>, groups Swiss License front/back, filters in the client, navigates to detail page.</td></tr><tr><td><code>Frontend/src/pages/private/admin-dashboard/DocumentsDetailPage.tsx</code></td><td>Detail page for one instructor and one document type</td><td>Reuses <code>GET_ALL_INSTRUCTORS</code>, finds the target instructor and document set in memory, renders profile + document viewer + status control.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/StatusDropdown.tsx</code></td><td>Status change control</td><td>Calls <code>UPDATE_DOCUMENT_STATUS</code>, refetches <code>GET_ALL_INSTRUCTORS</code>, supports collective update for grouped Swiss-license documents.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/DocumentUpdate/DocumentUpdateModal.tsx</code></td><td>Defines shared document GraphQL for admin/instructor tooling</td><td>Exports <code>UPDATE_DOCUMENT_STATUS</code>; also defines <code>GET_INSTRUCTOR_DOCUMENTS</code> and upload/update mutations used by broader document flows.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/DocumentSlider.tsx</code></td><td>Media/document preview helper</td><td>Used inside the detail page to browse document assets.</td></tr><tr><td><code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code></td><td>Shared instructor queries</td><td>Defines <code>GET_ALL_INSTRUCTORS</code>.</td></tr><tr><td><code>Frontend/src/types/Instructor.ts</code></td><td>TS models for instructor and document rows</td><td>Used by table/detail page.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-all-instructors" tabindex="-1"><code>GET_ALL_INSTRUCTORS</code> <a class="header-anchor" href="#get-all-instructors" aria-label="Permalink to &quot;`GET_ALL_INSTRUCTORS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code></li><li>Query field: <code>allInstructors</code></li><li>Returns instructor profile basics plus <code>documents { _id, documentType, documentUrl, status, createdAt, reSubmitted }</code></li><li>Used by: <ul><li><code>InstructorDocumentsTable.tsx</code></li><li><code>DocumentsDetailPage.tsx</code></li></ul></li></ul><h3 id="update-document-status" tabindex="-1"><code>UPDATE_DOCUMENT_STATUS</code> <a class="header-anchor" href="#update-document-status" aria-label="Permalink to &quot;`UPDATE_DOCUMENT_STATUS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/components/InstructorComponent/DocumentUpdate/DocumentUpdateModal.tsx</code></li><li>Mutation field: <code>updateDocumentStatus(documentId: ID!, status: String!)</code></li><li>Used by: <code>StatusDropdown.tsx</code></li><li>Refetch behavior: refetches <code>GET_ALL_INSTRUCTORS</code></li></ul><h3 id="get-instructor-documents" tabindex="-1"><code>GET_INSTRUCTOR_DOCUMENTS</code> <a class="header-anchor" href="#get-instructor-documents" aria-label="Permalink to &quot;`GET_INSTRUCTOR_DOCUMENTS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/components/InstructorComponent/DocumentUpdate/DocumentUpdateModal.tsx</code></li><li>Query field: <code>getInstructorDocuments(instructorId: ID!)</code></li><li>Note: part of the same document module, but the current admin documents table/detail flow mainly uses <code>GET_ALL_INSTRUCTORS</code> and filters client-side instead of using this query directly.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs.js</code></li><li>Relevant query fields: <ul><li><code>allInstructors: [Instructor!]!</code></li><li><code>getInstructorDocuments(instructorId: ID!): InstructorDocumentsResponse!</code></li></ul></li><li>Relevant mutation fields: <ul><li><code>updateDocumentStatus(documentId: ID!, status: String!): InstructorDocument!</code></li><li><code>updateDocumentStatusStudent(studentId: ID!, documentType: String!, status: DocumentStatus!): Student</code></li></ul></li><li>Relevant shared types: <ul><li><code>DocumentStatus</code></li><li><code>InstructorDocumentsResponse</code></li><li><code>InstructorDocument</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers.js</code></li><li>Relevant query resolvers: <ul><li><code>allInstructors</code><ul><li>Admin-only</li><li>Reads all instructors and returns profile fields plus <code>documents</code></li></ul></li><li><code>getInstructorDocuments</code><ul><li>Returns one instructor’s documents by instructor id</li></ul></li></ul></li><li>Relevant mutation resolvers: <ul><li><code>updateDocumentStatus</code><ul><li>Admin-only</li><li>Validates status against <code>pending | accepted | rejected</code></li><li>Finds instructor by <code>documents._id</code></li><li>If the document is <code>Swiss Driving License (Front)</code> or <code>Swiss Driving License (Back)</code>, updates both files together</li><li>Sends notification email through <code>notifyDocumentStatusParties</code></li></ul></li><li><code>updateDocumentStatusStudent</code><ul><li>Updates one student document by <code>studentId + documentType</code></li><li>Exists in backend, but this admin documents UI is centered on instructor documents</li></ul></li></ul></li></ul><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Admin opens <code>InstructorDocumentsTable.tsx</code>.</li><li><code>GET_ALL_INSTRUCTORS</code> returns instructors and embedded document arrays.</li><li>Frontend flattens documents into row items, groups Swiss-license front/back as one logical record, and applies client-side filters.</li><li>Clicking a row navigates to <code>DocumentsDetailPage.tsx</code>.</li><li>Detail page loads the same query result, finds <code>instructorId</code> and <code>documentType</code>, and renders the target document set.</li><li>Status change uses <code>StatusDropdown.tsx</code> -&gt; <code>UPDATE_DOCUMENT_STATUS</code>.</li><li>Backend updates the instructor document(s), may update both Swiss-license sides, sends email notification, and returns the updated document.</li><li>Frontend refetches <code>GET_ALL_INSTRUCTORS</code> so both the list and detail view stay current.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This module currently uses <strong>instructor documents</strong> as its primary data source. Student document status mutation exists in backend, but there is no dedicated student-documents admin screen wired to it here.</li><li>The detail page does not call a dedicated detail query; it reuses <code>GET_ALL_INSTRUCTORS</code> and filters locally.</li><li>Swiss driving license is intentionally treated as a grouped document in both frontend and backend.</li></ul>',23)])])}const p=t(s,[["render",a]]);export{h as __pageData,p as default};
